```java
public class GCD { 
    public static int computeGCD(int num1, int num2) { 
        if (num2 == 0) 
            return num1; 
        return computeGCD(num2, num1 % num2); 
    } 

    public static void main(String[] args) { 
        int num1 = 120; 
        int num2 = 360; 
        System.out.println(computeGCD(num1,num2)); 
    } 
}
```

