        hash_table = {}
# Step 8:  Initialize an empty string to store the result.

        result = ''
# Step 9:  Iterate through the characters in the input string.

        for item in s:
# Step 10:  Update the frequency of the character in the hash table.

            hash_table[item] = hash_table.get(item, 0) + 1
# Step 11:  Iterate through the items in the hash table to populate the bucket with characters based on their frequency.

        for (key, value) in hash_table.items():
            if bucket[value]:
                bucket[value].append((key, value))
            else:
                bucket[value] = [(key, value)]
# Step 12:  Iterate through the characters in the bucket in reverse order to generate the result string.

        for i in range(len(bucket) - 1, -1, -1):
