#include <iostream>
#include <string>

std::string repeatChar(std::string str, int n) {
  std::string output = "";  // create an empty string

  for (char c : str) {  // loop through each character in the string
    for (int i = 0; i < n; i++) {  // repeat each character n times
      output += c;  // append the character to the output string
    }
  }

  return output;  // return the resulting string
}

int main() {
